/**
 * Standard Salesforce Components
 *
 * These components are auto-generated by Salesforce or are standard components
 * that should exist in the org but don't need to be in the source project.
 *
 * References to these components should not cause deployment failures.
 */

import type { NodeId } from '../types/dependency.js';

/**
 * Experience Cloud (Sites) auto-generated components
 * These are created automatically when an Experience Cloud site is created
 */
export const EXPERIENCE_CLOUD_STANDARD_COMPONENTS = new Set<string>([
  // Static Resources
  'StaticResource:SiteSamples',

  // Lightning Components (prefixed with c:)
  'LightningComponentBundle:sitelogin',
  'LightningComponentBundle:siteheader',
  'LightningComponentBundle:sitefooter',
  'LightningComponentBundle:sitepoweredby',

  // Standard Visualforce Components
  'VisualforceComponent:SiteLogin',
  'VisualforceComponent:SiteHeader',
  'VisualforceComponent:SiteFooter',
  'VisualforceComponent:SitePoweredBy',
]);

