/**
 * Check if a component is auto-generated by Experience Bundle
 * These components are in source but may reference standard components
 */
export function isExperienceBundleComponent(nodeId: NodeId): boolean {
  return EXPERIENCE_BUNDLE_AUTO_GENERATED.has(nodeId);
}

/**
 * Check if an error is safe to ignore for Experience Bundle components
 * These components reference standard components that should exist in org
 */
export function isSafeToIgnoreExperienceBundleErrors(componentName: string, errorMessage: string): boolean {
  // Build component identifier (componentType:fullName)
  // componentName can be just the name or "componentType:fullName"
  const componentId = componentName.includes(':') ? componentName : `Unknown:${componentName}`;

  // Check if component is auto-generated by Experience Bundle
  // Check both the full identifier and just the name
  const isAutoGenerated = EXPERIENCE_BUNDLE_AUTO_GENERATED.has(componentId) ||
    Array.from(EXPERIENCE_BUNDLE_AUTO_GENERATED).some(
      (autoGen) => {
        const autoGenName = autoGen.split(':')[1];
        return componentName === autoGenName || componentName.endsWith(`:${autoGenName}`);
      }
    );

  if (!isAutoGenerated) {
    return false;
  }

  // Check if error is about standard components that should exist in org
  const standardComponentErrors = [
    'SiteSamples',
    'sitelogin',
    'SiteLogin',
    'SiteHeader',
    'SiteFooter',
    'SitePoweredBy',
    'does not exist',
    'Check spelling',
  ];

  return standardComponentErrors.some((stdComp) =>
    errorMessage.includes(stdComp)
  );
}

/**
 * Check if a component is a standard/auto-generated component
 * that should exist in the org but doesn't need to be in source
 */
export function isStandardComponent(nodeId: NodeId): boolean {
  return EXPERIENCE_CLOUD_STANDARD_COMPONENTS.has(nodeId);
}

/**
 * Check if a dependency reference is to a standard component
 * These references are safe and should not cause deployment failures
 */
export function isStandardComponentReference(nodeId: NodeId): boolean {
  // Check exact match
  if (EXPERIENCE_CLOUD_STANDARD_COMPONENTS.has(nodeId)) {
    return true;
  }

  // Check for Lightning Component references (c: prefix)
  if (nodeId.startsWith('LightningComponentBundle:c:')) {
    const componentName = nodeId.replace('LightningComponentBundle:c:', '').toLowerCase();
    if (['sitelogin', 'siteheader', 'sitefooter', 'sitepoweredby'].includes(componentName)) {
      return true;
    }
  }

  // Check for StaticResource:SiteSamples variations
  if (nodeId.includes('SiteSamples')) {
    return true;
  }

  return false;
}

